DELETE FROM responsaveis WHERE cpf IN ('94411122233','94444455566'); DELETE FROM responsavel_usuario WHERE responsavel_id NOT IN (SELECT id FROM responsaveis); DELETE FROM responsavel_usuario WHERE usuario_id NOT IN (SELECT id FROM usuarios); DELETE FROM notas WHERE aluno_id NOT IN (SELECT id FROM alunos); DELETE FROM acompanhamentos WHERE aluno_id NOT IN (SELECT id FROM alunos); SELECT (SELECT COUNT(*) FROM responsaveis WHERE cpf IN ('94411122233','94444455566')) AS resp_orfaos, (SELECT COUNT(*) FROM responsaveis) AS total_resp, (SELECT COUNT(*) FROM responsavel_usuario) AS vinculos, (SELECT COUNT(*) FROM notas) AS notas, (SELECT COUNT(*) FROM acompanhamentos) AS acomp, (SELECT COUNT(*) FROM usuarios) AS usuarios, (SELECT COUNT(*) FROM alunos) AS alunos;